<template>
  <el-dialog v-model="open" title="执行详情" width="1000px" class="flash-dialog" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="batch"><div class="toolbar"><strong>{{ batch.source === 'post_sync' ? '执行后同步' : batch.source === 'scheduled' ? '定时计划批次' : '手动操作批次' }}</strong><span>{{ operationLabel }}</span><span>{{ flashTime(batch.created_at) }}（北京）</span><el-button v-if="canExecute && !batch.finished_at" :loading="busy" @click="action('stop')">安全停止</el-button><el-button v-if="canExecute" :loading="busy" @click="action('reconcile')">重新核对</el-button></div><article v-for="task in batch.tasks" :key="task.id" class="task-card"><h3>{{ task.store_name }} · {{ taskLabels[task.status] || '待核对' }}</h3><p>{{ task.message }}<template v-if="createsActivities"> · 完成 {{ task.completed }}/{{ task.requested }} 个时段</template></p><p v-if="task.retry_paused" class="retry-pause">{{ task.retry_pause_reason }}<el-button v-if="canExecute" :loading="busy" @click="resumeTask(task)">继续核对原任务</el-button></p><small>连续无进展 {{ task.no_progress_count || 0 }} 轮 · 历史重试 {{ task.retry_count || 0 }} 次</small><small>排队 {{ duration(task.queue_ms) }} · 执行 {{ duration(task.execution_ms) }} · 重试等待 {{ duration(task.waiting_ms) }}<template v-if="task.next_attempt_at"> · 下次核对 {{ flashTime(task.next_attempt_at) }}</template></small><p v-if="task.sync">执行后同步：{{ taskLabels[task.sync.status] || '待核对' }} · {{ task.sync.message }}</p><el-alert v-if="task.notification_error" :title="task.notification_error" type="warning" :closable="false"/><div v-for="intent in task.intents" :key="intent.id" class="intent"><p>活动 {{ intent.platform_id || (createsActivities ? '尚未确认创建' : '编号待核对') }}</p><p v-if="intent.result.message">{{ intent.result.message }}</p><p v-if="createsActivities">{{ specificationSummary(intent) }}</p><p v-if="unconfirmedCount(intent)">{{ unconfirmedCount(intent) }} 个规格待核对，尚不能确认参加结果</p><p v-if="intent.target.start_time">目标时段：{{ flashTime(intent.target.start_time, task.timezone) }} 至 {{ flashTime(intent.target.end_time, task.timezone) }}（{{ task.timezone || 'Asia/Shanghai' }}）</p><p v-for="a in intent.result.adjustments || []" :key="`${a.item_id}:${a.model_id}`">规格 {{ a.model_id }} 库存已调整：{{ a.before }} → {{ a.after }}（可用 {{ a.available }}）；价格保持不变</p><p v-for="reason in rejectionSummary(intent)" :key="reason">{{ reason }}</p><details><summary>查看规格及技术编号</summary><small>意图 {{ intent.id }} · 时段 {{ intent.target.timeslot_id || '—' }}</small><el-table :data="intent.result.specifications || []" border><el-table-column prop="item_id" label="商品编号" min-width="120"/><el-table-column prop="model_id" label="规格编号" min-width="120"/><el-table-column prop="reason" label="结果" min-width="240"/><el-table-column prop="price" label="活动价"/><el-table-column prop="stock" label="库存"/></el-table></details></div></article><p v-for="n in batch.notifications" :key="n.id">{{ n.name }}：{{ n.message || '待发送' }}<el-button v-if="canExecute && ['failed','failed_or_unknown'].includes(n.status)" link @click="action('retry_notification',{notification_id:n.id})">单独重试通知</el-button></p></template><template #footer><el-button @click="open = false">收起</el-button><el-button v-if="batch?.finished_at" @click="$emit('close')">关闭任务提示</el-button></template></el-dialog>
  <aside v-if="batch && !open && !['scheduled','post_sync'].includes(batch.source)" class="task-bar"><span>{{ operationLabel }} · {{ batch.tasks.filter(finished).length }}/{{ batch.tasks.length }} 店已结束</span><el-button link type="primary" @click="open = true">展开</el-button><el-button v-if="batch.finished_at" link @click="$emit('close')">关闭</el-button></aside>
</template>
<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { ElMessageBox } from 'element-plus';
import { flashRequest, flashTime, taskLabels, finished } from '../../api/flashSales';
const props = defineProps({batchId:{type:String,required:true},canExecute:Boolean}); defineEmits(['close']);
const open = ref(true), batch = ref(null), error = ref(''), busy = ref(false);
const operationLabel = computed(() => ({run:'补建闪购',copy:'复制活动',sync:'同步活动',toggle:'切换活动状态',delete:'删除活动'}[batch.value?.operation] || '执行'));
const createsActivities = computed(() => ['run','copy'].includes(batch.value?.operation));
let timer, disposed = false, generation = 0;
async function load(id, gen) {try {const result = await flashRequest(`batches/${id}/`);if (!disposed && gen === generation) {batch.value = result;error.value = '';}} catch(e) {if (!disposed && gen === generation) error.value = e?.response?.data?.message || e.message;}}
async function poll(id,gen) {await load(id,gen);if (!disposed && gen === generation) timer = setTimeout(() => poll(id,gen),5000);}
watch(() => props.batchId,id => {clearTimeout(timer);batch.value = null;error.value = '';busy.value = false;open.value = true;poll(id,++generation);},{immediate:true});
async function action(name,extra={}) {if (busy.value) return;const id = props.batchId, gen = generation;busy.value = true;try {await flashRequest(`batches/${id}/`,'post',{action:name,...extra});if (!disposed && gen === generation) await load(id,gen);} catch(e) {if (!disposed && gen === generation) error.value = e?.response?.data?.message || e.message;} finally {if (!disposed && gen === generation) busy.value = false;}}
async function resumeTask(task) {
  const id = props.batchId, gen = generation;
  try {await ElMessageBox.confirm('继续当前原任务：已提交的写入先回读核对，不重新创建；尚未提交的步骤会继续执行。', '继续核对原任务', {confirmButtonText:'确认继续',cancelButtonText:'取消',type:'warning'});}
  catch {return;}
  if (!disposed && id === props.batchId && gen === generation) await action('resume',{task_id:task.id,confirmed:true});
}
function duration(value) {return value == null ? '尚未开始' : `${Math.round(value / 1000)} 秒`;}
function rejectionSummary(intent) {const counts = new Map();for (const row of intent.result.specifications || []) if (row.state === 'rejected') {const reason = row.reason || '平台拒绝参加';counts.set(reason,(counts.get(reason)||0)+1);}return [...counts].map(([reason,count]) => `${count} 个规格被拒绝：${reason}`);}
function unconfirmedCount(intent) {return (intent.result.specifications || []).filter(row => !['enabled','rejected'].includes(row.state)).length;}
function specificationSummary(intent) {
  const rows = intent.result.specifications;
  if (!rows?.length) return intent.result.enabled_count == null ? '规格结果待核对' : `${intent.result.enabled_count} 个规格启用`;
  return `已启用 ${rows.filter(row => row.state === 'enabled').length} / 被拒绝 ${rows.filter(row => row.state === 'rejected').length} / 待核对 ${unconfirmedCount(intent)}`;
}
onBeforeUnmount(() => {disposed = true;clearTimeout(timer);});
</script>
<style scoped>
.toolbar,.task-bar {display:flex;align-items:center;gap:12px;flex-wrap:wrap}.task-card {border:1px solid var(--el-border-color);padding:16px;margin:16px 0;border-radius:6px}.task-card h3 {margin:0}.intent {margin-top:16px} small {display:block;color:var(--el-text-color-secondary)} summary {cursor:pointer;color:var(--el-color-primary);margin:12px 0}.task-bar {position:fixed;bottom:20px;right:24px;max-width:calc(100vw - 48px);z-index:100;padding:12px 16px;border:1px solid var(--el-border-color);border-radius:8px;background:var(--el-bg-color);box-shadow:var(--el-box-shadow-light)} @media(max-width:600px) {.task-bar {right:12px;bottom:12px;max-width:calc(100vw - 24px)}}
</style>
